import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}


class _JSONPostRequestHandler(http.server.BaseHTTPRequestHandler):
    def _send_json(self, status_code, payload):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status_code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        content_type = self.headers.get("content-type")
        if not content_type:
            self._send_json(
                400,
                {
                    "status": "error",
                    "message": "Content-Type header is not application/json",
                },
            )
            return

        mime_type, _ = cgi.parse_header(content_type)
        if mime_type.lower() != "application/json":
            self._send_json(
                400,
                {
                    "status": "error",
                    "message": "Content-Type header is not application/json",
                },
            )
            return

        try:
            content_length = int(self.headers.get("content-length", "0"))
        except (TypeError, ValueError):
            content_length = 0

        raw_body = self.rfile.read(content_length) if content_length > 0 else b""

        try:
            request_data = json.loads(raw_body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._send_json(400, {"status": "error", "message": "Invalid JSON"})
            return

        if not isinstance(request_data, dict) or "data" not in request_data:
            self._send_json(
                400,
                {
                    "status": "error",
                    "message": "No data key in request",
                },
            )
            return

        self._send_json(200, SUCCESS_RESPONSE)

    def log_message(self, format, *args):
        return


def task_func():
    return _JSONPostRequestHandler
